normalState.source:
function (state, playData) {
                var nextState = state;
                switch (state) {
                    case 0 /* BaseGame */:
                        if (playData.getIsFreeSpin()) {
                            nextState = 1 /* FreeGameTrigger */;
                        }
                        if (playData.getCustomData().gameInfoData.BigBet) {
                            nextState = 5 /* BigBet */;
                        }
                        break;
                    case 1 /* FreeGameTrigger */:
                        nextState = 2 /* FreeGame */;
                        break;
                    case 2 /* FreeGame */:
                        if (playData.getCustomData().freeSpinData.lastFreeSpin) {
                            nextState = 4 /* FreeGameEnd */;
                        }
                        if (playData.getCustomData().exchangeData != null) {
                            nextState = 3 /* Exchange */;
                        }
                        break;
                    case 5 /* BigBet */:
                        if (playData.getCustomData().gameInfoData.BigBetRemainingSpin == 0) {
                            if (!playData.getIsFreeSpin() && playData.getCustomData().pharaohsBonusData == null)
                                nextState = 6 /* BigBetSpinEnd */;
                            else if (playData.getIsFreeSpin() && playData.getCustomData().pharaohsBonusData == null)
                                nextState = 1 /* FreeGameTrigger */;
                            else if (!playData.getIsFreeSpin() && playData.getCustomData().pharaohsBonusData != null)
                                nextState = 7 /* PharaohsBonusTrigger */;
                        }
                        break;
                    case 8 /* PharaohsBonus */:
                        if (playData.getCustomData().pharaohsBonusData != null && playData.getCustomData().pharaohsBonusData.LastFreeSpin) {
                            nextState = 5 /* BigBet */;
                        }
                        else {
                            nextState = 1 /* FreeGameTrigger */;
                        }
                        break;
                    default:
                        break;
                }
                return nextState;
            }

