var LOPFreeSpinXMLParser = (function () {
            function LOPFreeSpinXMLParser() {
            }
            LOPFreeSpinXMLParser.populateFreeGameData = function (node, freeSpinData) {
                if (node.attributes.getNamedItem("freeSpinTriggerWin"))
                    freeSpinData.triggerWin = parseInt(node.attributes.getNamedItem("freeSpinTriggerWin").value, 10);
                if (node.attributes.getNamedItem("reelSetIndex"))
                    freeSpinData.reelSetIndex = parseInt(node.attributes.getNamedItem("reelSetIndex").value, 10);
                if (node.attributes.getNamedItem("totalFreeSpinsTriggered"))
                    freeSpinData.totalFreeSpinTriggered = parseInt(node.attributes.getNamedItem("totalFreeSpinsTriggered").value, 10);
                if (node.attributes.getNamedItem("lastFreeSpin"))
                    freeSpinData.lastFreeSpin = node.attributes.getNamedItem("lastFreeSpin").value == "Y";
                if (node.attributes.getNamedItem("remainingFreeSpins"))
                    freeSpinData.totalFreeSpinTriggered = parseInt(node.attributes.getNamedItem("remainingFreeSpins").value, 10);
                if (node.attributes.getNamedItem("inPick"))
                    freeSpinData.inPick = node.attributes.getNamedItem("inPick").value == "Y";
                if (node.attributes.getNamedItem("pickIndex"))
                    freeSpinData.pickIndex = parseInt(node.attributes.getNamedItem("pickIndex").value, 10);
                if (node.attributes.getNamedItem("bonusInfo")) {
                    var bonusInfo = node.attributes.getNamedItem("bonusInfo").value;
                    var bonusInfoArr = bonusInfo.split(",");
                    for (var i = 0; i < bonusInfoArr.length; i++) {
                        var bInfo = new legendofthepharaohs.BonusInfo();
                        bInfo.bonusCategory = Number(bonusInfoArr[i].split("|")[0]);
                        bInfo.bonusSubType = Number(bonusInfoArr[i].split("|")[1]);
                        freeSpinData.setBonusInformation(bInfo);
                    }
                }
            };
            LOPFreeSpinXMLParser.populateExchangeData = function (node, exchangeData) {
                if (node.attributes.getNamedItem("retriggerFreeSpinsCount"))
                    exchangeData.retriggerCount = parseInt(node.attributes.getNamedItem("retriggerFreeSpinsCount").value, 10);
                if (node.attributes.getNamedItem("retriggerBandSet"))
                    exchangeData.reelSetIndex = parseInt(node.attributes.getNamedItem("retriggerBandSet").value, 10);
                if (node.attributes.getNamedItem("exchangeBypassed"))
                    exchangeData.exchangeByPassed = node.attributes.getNamedItem("exchangeBypassed").value == "Y";
                if (node.attributes.getNamedItem("bestStrategy"))
                    exchangeData.strategyBest = parseInt(node.attributes.getNamedItem("bestStrategy").value, 10);
                if (node.attributes.getNamedItem("retriggerBonusInfo")) {
                    var bonusInfo = node.attributes.getNamedItem("retriggerBonusInfo").value;
                    var bonusInfoArr = bonusInfo.split(",");
                    for (var i = 0; i < bonusInfoArr.length; i++) {
                        var bInfo = new legendofthepharaohs.BonusInfo();
                        bInfo.bonusCategory = Number(bonusInfoArr[i].split("|")[0]);
                        bInfo.bonusSubType = Number(bonusInfoArr[i].split("|")[1]);
                        exchangeData.setBonusInformation(bInfo);
                    }
                }
            };
            return LOPFreeSpinXMLParser;
        })();
        legendofthepharaohs.LOPFreeSpinXMLParser = LOPFreeSpinXMLParser;

