                    this.bigBetMenu.setGameData(this.gameData);
                    this.pharaohsBonus.setGameData(this.gameData);
                    var isColossal = this.isFeatureTrigerred(2 /* Colossal */, this.gameData.getCustomData().freeSpinData.getBonusInformation());
                    //check for pick status
                    if (this.gameData.getCustomData().freeSpinData.inPick) {
                        this.gameState = 2 /* FreeGame */;
                        this.freeSpin.checkForNextSpin(isColossal);
                        return;
                    }
                    //check in pharaohs bonus
                    if (this.gameData.getCustomData().pharaohsBonusData != null && this.gameData.getCustomData().pharaohsBonusData.InPharoahs) {
                        this.gameState = 8 /* PharaohsBonus */;
                    }
                    //change reel set during spin
                    if (isColossal && (this.gameState == 1 /* FreeGameTrigger */ || this.gameState == 2 /* FreeGame */)) {
                        this.slot.generateColossalReelSet(this.gameData.getReelSetIndex(), this.getColossalBonusData().bonusSubType, this.isColossalWildSymSame());
                        this.slot.changeToFeatureReelSet(-1);
                    }
                    else if (this.gameData.getCustomData().pharaohsBonusData == null || (this.gameData.getCustomData().pharaohsBonusData != null && !this.gameData.getCustomData().pharaohsBonusData.InPharoahs)) {
                        this.slot.changeToFeatureReelSet(this.gameData.getReelSetIndex());
                    }
                    ///
                    if (this.gameData.getCustomData().gameInfoData.BigBet && !this.gameData.getIsFreeSpin() && this.gameState != 8 /* PharaohsBonus */) {
                        this.gameState = 5 /* BigBet */;
                        this.bigBetReelSetIndex = this.gameData.getReelSetIndex();
                    }
                    if (this.gameState == 0 /* BaseGame */ || this.gameState == 5 /* BigBet */) {
                        this.slot.getWinDisplayController().configure(this.gameData, false);
                        this.slot.setStopPositions(response.getGameData().getStopPositions());
                    }
                    else if (this.gameState == 2 /* FreeGame */ || this.gameState == 1 /* FreeGameTrigger */) {
                        this.freeSpin.configureResultsDisplay();
                    }
                    else if (this.gameState == 8 /* PharaohsBonus */) {
                        this.pharaohsBonus.startRotate();
                    }
                    else {
                        console.log('Incorrect game state on play response');
                    }
                    this.gameState = this.getNextState(this.gameState, this.gameData);
                }
            }

