                    });
                }
                else if (this.isFgActive && !this.isExchange) {
                    this.winDisplayController.stop();
                    this.oneCycleComplete = true;
                    this.checkWinAnimComplete();
                }
                else if (this.isFgActive && this.isExchange) {
                    this.winDisplayController.stop();
                    this.isExchange = false;
                    this.audioModel.playFgRumble();
                    this.audioModel.stopFgBonusLoop();
                    if (this.isExchangeByPassed) {
                        this.changeRetriggerBonusReelSet();
                        this.featureReveal.setLastSpinFg(true);
                        this.featureDisplay.setCallbackFlag(true);
                        this.featureReveal.playReveal();
                        this.featureDisplay.destroy();
                        this.audioModel.playBonusTrigerredSound(this.gameData.getCustomData().freeSpinData.getBonusInformation().length);
                        this.freeSpinView.setFgRemaining(this.exchangeFgRemaining + 1);
                        this.fgRemaining = this.exchangeFgRemaining;
                        this.freeSpinView.showLastSpinLabel(true);
                    }
                    else {
                        this.fsExchange.setGameData(this.gameData.getCustomData().freeSpinData, this.gameData.getCustomData().exchangeData);
                        this.fsExchange.create(this.totalWin);
                    }
                }
            }
